"""Bone Reaper animations (your "menacing undead skeleton dragon" set): 17-frame flap loop,
the head-back breath frames, and the mid-air collapse used for its death. Frames are 168x128 like the other HD dragons."""
import base64, zlib, math
import pygame

FRAMES = {
  'fly': (17, ''),
  'breath': (17, ''),
  'death': (17, ''),
}
BREATH_LOOP = (6, 7, 8, 9, 10, 11, 12, 13)      # mouth open, glowing: looped while breathing
_RAW, _F, _R = {}, {}, {}
W, H = 168, 128


def _frame(name, i):
  n, data = FRAMES[name]
  i %= n
  k = (name, i)
  s = _F.get(k)
  if s is None:
    raw = _RAW.get(name)
    if raw is None:
      raw = _RAW[name] = zlib.decompress(base64.b64decode(data))
    m = W * H * 4
    s = _F[k] = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (W, H), 'RGBA').copy()
  return s


def bone_frame(name, i, tb=0):
  """frame i of 'fly' / 'breath' / 'death', tilted by tb steps (6 degrees each, nose down for +)."""
  if name == 'breath':
    i = BREATH_LOOP[i % len(BREATH_LOOP)]
  if not tb:
    return _frame(name, i)
  k = (name, i % FRAMES[name][0], tb)
  s = _R.get(k)
  if s is None:
    src = _frame(name, i)
    r = pygame.transform.rotate(src, -tb * 6)
    s = pygame.Surface((W, H), pygame.SRCALPHA)
    s.blit(r, (W // 2 - r.get_width() // 2, H // 2 - r.get_height() // 2))
    _R[k] = s
  return s


def fly_index(wing):
  """17-frame flap loop: one frame every 2 game frames while flapping (wing grows 0.38 a frame), slower while gliding."""
  return int(wing / 0.76) % 17


def bone_death(i):
  return _frame('death', max(0, min(16, i)))


def bone_hurt(i):                                 # (kept for older callers)
  return _frame('fly', i)
